import org.junit.jupiter.api.Test;

/**
 * Protective concurrent-reader control for the first visible-name comparisons of immutable native rows. The start latch
 * aligns initial access opportunities; this test does not claim that a memory-model race is deterministic or that every
 * run observes simultaneous cache initialization.
 */
class NativeSortedNamesConcurrentFirstComparisonTest {
	private static final int PROJECTION_WIDTH = 129;
	private static final int READER_COUNT = 12;
	private static final int COMPARISONS_PER_READER = 32;
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void concurrentFirstComparisonsKeepWideVisibleDomainsAndGenericNameOrder() throws Exception {
		ValueRejectingSource source = new ValueRejectingSource();
		NativeRow first = nativeRow(source, "v000", "v064", "v128");
		NativeRow differentFirst = nativeRow(source, "v001", "v064", "v127");
		NativeRow differentMiddle = nativeRow(source, "v000", "v065", "v127");
		NativeRow differentLast = nativeRow(source, "v000", "v064", "v127");
		OrderComparator comparator = comparator();
		List<Comparison> pairs = List.of(
				comparison(first, differentFirst, comparator),
				comparison(first, differentMiddle, comparator),
				comparison(differentLast, first, comparator));

		for (Comparison comparison : pairs) {
			assertEquals(comparison.left.domain, comparison.ordinaryLeft.getBindingNames());
			assertEquals(comparison.right.domain, comparison.ordinaryRight.getBindingNames());
			assertEquals(sorted(comparison.left.domain), sorted(comparison.ordinaryLeft.getBindingNames()));
			assertEquals(sorted(comparison.right.domain), sorted(comparison.ordinaryRight.getBindingNames()));
			assertEquals(comparison.left.domain.size(), comparison.left.row.size());
			assertEquals(comparison.right.domain.size(), comparison.right.row.size());
			assertEquals(-1, comparison.expectedOrder,
					"independent generic mappings establish the exact expected lexicographic position");
		}

		CountDownLatch readersReady = new CountDownLatch(READER_COUNT);
		CountDownLatch beginComparisons = new CountDownLatch(1);
		List<Future<?>> futures = new ArrayList<>(READER_COUNT);
		try (ExecutorService readers = Executors.newFixedThreadPool(READER_COUNT)) {
			for (int reader = 0; reader < READER_COUNT; reader++) {
				futures.add(readers.submit(() -> {
					readersReady.countDown();
					beginComparisons.await();
					for (int attempt = 0; attempt < COMPARISONS_PER_READER; attempt++) {
						for (Comparison comparison : pairs) {
							assertEquals(comparison.expectedOrder,
									Integer.signum(comparator.compare(comparison.left.row, comparison.right.row)));
							assertEquals(-comparison.expectedOrder,
									Integer.signum(comparator.compare(comparison.right.row, comparison.left.row)));
						}
					}
					return null;
				}));
			}
			readersReady.await();
			beginComparisons.countDown();
			for (Future<?> future : futures) {
				future.get();
			}
		}

		for (NativeRow row : List.of(first, differentFirst, differentMiddle, differentLast)) {
			assertEquals(row.domain, row.row.getBindingNames());
			for (int i = 0; i < PROJECTION_WIDTH; i++) {
				String name = projectionName(i);
				if (!row.domain.contains(name)) {
					assertFalse(row.row.hasBinding(name), "row must preserve absent projected slot " + name);
				}
			}
		}
		assertEquals(0, source.valueResolutions.get(), "name-only comparisons must not materialize native values");
	}

	private static Comparison comparison(NativeRow left, NativeRow right, OrderComparator comparator) {
		QueryBindingSet ordinaryLeft = ordinaryMapping(left.domain);
		QueryBindingSet ordinaryRight = ordinaryMapping(right.domain);
		int expectedOrder = Integer.signum(comparator.compare(ordinaryLeft, ordinaryRight));
		return new Comparison(left, right, ordinaryLeft, ordinaryRight, expectedOrder);
	}

	private static NativeRow nativeRow(ValueRejectingSource source, String... visibleNames) {
		Set<String> domain = Set.of(visibleNames);
		String[] projectionNames = new String[PROJECTION_WIDTH];
		int[] sourceSlots = new int[PROJECTION_WIDTH];
		long[] ids = new long[PROJECTION_WIDTH];
		Arrays.fill(ids, NativeLmdbQuerySource.UNKNOWN_ID);
		for (int i = 0; i < PROJECTION_WIDTH; i++) {
			projectionNames[i] = projectionName(i);
			sourceSlots[i] = i;
			if (domain.contains(projectionNames[i])) {
				ids[i] = 30_000L + i;
			}
		}
		return new NativeRow(new NativeProjectedBindingSet(source, projectionNames, sourceSlots, ids), domain);
	}

	private static String projectionName(int index) {
		return String.format(java.util.Locale.ROOT, "v%03d", index);
	}

	private static QueryBindingSet ordinaryMapping(Set<String> names) {
		QueryBindingSet result = new QueryBindingSet();
		for (String name : names) {
			result.setBinding(name, VF.createLiteral(name));
		}
		return result;
	}

	private static List<String> sorted(Set<String> names) {
		return names.stream().sorted().toList();
	}

	private static OrderComparator comparator() {
		return new OrderComparator(null, new Order(), new ValueComparator(),
				new QueryEvaluationContext.Minimal(VF.createLiteral("now"), null, null));
	}

	private record NativeRow(NativeProjectedBindingSet row, Set<String> domain) {
	}

	private record Comparison(NativeRow left, NativeRow right, QueryBindingSet ordinaryLeft,
			QueryBindingSet ordinaryRight, int expectedOrder) {
	}

	private static final class ValueRejectingSource implements NativeLmdbQuerySource {
		private final AtomicInteger valueResolutions = new AtomicInteger();

		@Override
		public long idOf(Value value) {
			throw new AssertionError("name comparison must not encode a value");
		}

		@Override
		public Value lazyValue(long id) {
			valueResolutions.incrementAndGet();
			throw new AssertionError("name comparison must not resolve a value");
		}

		@Override
		public Object idSpace() {
			return this;
		}

		@Override
		public RecordIterator statements(long subj, long pred, long obj, long context) throws IOException {
			throw new AssertionError("name comparison must not open a source iterator");
		}

		@Override
		public long count(long subj, long pred, long obj, long context) {
			throw new AssertionError("name comparison must not count source rows");
		}

		@Override
		public boolean has(long subj, long pred, long obj, long context) {
			throw new AssertionError("name comparison must not probe source rows");
		}

		@Override
		public double estimate(long subj, long pred, long obj, long context) {
			throw new AssertionError("name comparison must not estimate source rows");
		}

		@Override
		public boolean hasStatementsInSource() {
			return false;
		}
	}
}
